BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('stats8-q01', '機械学習との接点',
   'クラス新聞係の2人が、お小遣いの使いすぎを別々の目的で調べている。1人は「なぜお小遣いが減るのか、理由のしくみを説明したい」。もう1人は「来月いくら使うかを、できるだけ当てたい」。後者の目的に一番近い分野はどれ？',
   NULL::text,
   '["機械学習（予測を当てることが目的）", "仮説検定（差があるかどうかを判定する）", "相関分析（2つの量の関係を調べる）", "記述統計（データの特徴を要約する）"]',
   0, '[0]', 'single',
   '{"asked": "統計と機械学習は何が違うのか、目的で見分ける。", "point": "「なぜ起きるかを説明したい」なら統計、「次に何が起きるかを当てたい」なら機械学習。", "kid": "統計も機械学習も、同じデータの山を使う仲間どうし。でも統計は「なぜそうなるか、理由やしくみを知りたい」ときに向いていて、機械学習は「理由はひとまず置いておいて、とにかく次の答えを当てたい」ときに向いている。", "eg": "同じ体温計を使っても、「なぜ熱が出たのか原因を調べる医者」と「この体温の伸び方なら明日は下がりそうと当てる予報屋」では、見ているゴールが違う。データの使い方の向きが違うだけで、道具そのものは似ている。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><line x1=\"170\" y1=\"14\" x2=\"170\" y2=\"132\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><text x=\"88\" y=\"26\" fill=\"#e8eaf0\" font-size=\"13\" text-anchor=\"middle\" font-weight=\"600\">統計</text><text x=\"88\" y=\"44\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">なぜ減るのか</text><text x=\"88\" y=\"58\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">理由を説明したい</text><circle cx=\"60\" cy=\"86\" r=\"4\" fill=\"#60a5fa\"/><circle cx=\"80\" cy=\"80\" r=\"4\" fill=\"#60a5fa\"/><circle cx=\"100\" cy=\"90\" r=\"4\" fill=\"#60a5fa\"/><circle cx=\"118\" cy=\"82\" r=\"4\" fill=\"#60a5fa\"/><text x=\"88\" y=\"108\" fill=\"#6ab08d\" font-size=\"9.5\" text-anchor=\"middle\">→ しくみ・原因が主役</text><text x=\"254\" y=\"26\" fill=\"#e8eaf0\" font-size=\"13\" text-anchor=\"middle\" font-weight=\"600\">機械学習</text><text x=\"254\" y=\"44\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">来月いくら使う?</text><text x=\"254\" y=\"58\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">数を当てたい</text><text x=\"254\" y=\"86\" fill=\"#60a5fa\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"600\">3000円 → ?円</text><text x=\"254\" y=\"108\" fill=\"#c9a04a\" font-size=\"9.5\" text-anchor=\"middle\">→ 当たること自体が主役</text></svg>", "terms": [["機械学習", "データから規則を自動で学び、新しいデータへの答えを予測する分野"], ["予測", "まだ分かっていない値を、手元のデータから前もって当てること"]], "think": "「理由を知りたいのか、当てたいだけなのか」で道具を選ぶのがカギ。理由を知りたいときは、なぜその結果が起きたかを人が読んで納得できる形にする必要がある。当てたいだけのときは、途中のしくみが人には分かりにくくても、当たる確率が高ければそれでよい。この「説明できることを優先するか、当たることを優先するか」の違いが、統計と機械学習の使い分けを決める。", "vs": "統計と機械学習は使う道具や計算が重なることも多く、はっきり線引きできない場合もある。ただし目的を聞かれたときは、「理由の説明」か「予測そのもの」かで考えると迷いにくい。", "why_asked": "この先の混同行列やROC曲線のような機械学習の道具は、これまでの統計の道具と発想が少し違う。まず「機械学習は予測を当てにいく分野」という立ち位置を押さえておかないと、あとの用語がなぜ生まれたのか腹落ちしない。", "usecase": "お小遣いアプリの「来月の使いすぎ予測」、天気アプリの「明日の降水確率」、ネット通販の「次に買いそうな商品のおすすめ」。どれも「理由の説明」より「当てること」を優先する場面。", "opt": ["正解。来月いくら使うかという未来の数を当てることが目的なので、予測を最優先する機械学習の考え方に近い。", "仮説検定は「差がある/ない」を判定する統計の道具で、来月の金額そのものを当てる目的とは違う。", "相関分析は2つの量が一緒に動くかどうかを調べる道具で、来月の金額を予測する目的とは違う。", "記述統計はすでにあるデータの特徴を要約する道具で、まだ起きていない来月の金額を当てる目的とは違う。"]}'),

  ('stats8-q02', '機械学習との接点',
   '先生がクラスに2種類のカードを配った。1つは「表に問題、裏に正解」が書いてあるカード。もう1つは「絵だけが描かれたカードを渡して、似ている絵どうしを自分で山分けしてね」というカード。正解つきのカードで練習して、新しい問題にも答えられるようにする学び方を何と呼ぶ？',
   NULL::text,
   '["教師あり学習（答え付きの問題で練習する）", "教師なし学習（答えなしで仲間分けさせる）", "強化学習（行動の結果に応じて報酬を与える）", "深層学習（層を重ねたニューラルネットを使う）"]',
   0, '[0]', 'single',
   '{"asked": "機械学習の中でも「答えを見せて練習させる」やり方の名前。", "point": "答え（正解ラベル）付きのデータで練習させ、新しいデータの答えを当てられるようにするのが教師あり学習。", "kid": "教師あり学習は、問題と正解がセットになったカードで勉強するやり方。何度も「問題→正解」を見せて練習させると、正解が書いていない新しい問題を渡されても、近い答えを言えるようになる。", "eg": "漢字ドリルで、問題の下にうっすら答えが書いてあるページを何十回も解くと、答えが隠れたテストでも書けるようになる。あの「答え付きで練習して、答えなしでも解けるようにする」流れそのもの。", "viz": "<svg viewBox=\"0 0 340 132\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">答え付きで練習 / 答えなしで仲間分け</text><rect x=\"26\" y=\"30\" width=\"90\" height=\"34\" rx=\"5\" fill=\"none\" stroke=\"#60a5fa\"/><text x=\"71\" y=\"44\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">問題: 3+4=?</text><text x=\"71\" y=\"58\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">答え: 7 (付き)</text><line x1=\"126\" y1=\"47\" x2=\"150\" y2=\"47\" stroke=\"#60a5fa\"/><polygon points=\"158,47 149,42.5 149,51.5\" fill=\"#60a5fa\"/><text x=\"75\" y=\"82\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">教師あり学習</text><text x=\"75\" y=\"96\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">答えを見て練習し予測する</text><circle cx=\"210\" cy=\"38\" r=\"6\" fill=\"#60a5fa\"/><circle cx=\"228\" cy=\"34\" r=\"6\" fill=\"#60a5fa\"/><circle cx=\"270\" cy=\"42\" r=\"6\" fill=\"#c9a04a\"/><circle cx=\"288\" cy=\"36\" r=\"6\" fill=\"#c9a04a\"/><circle cx=\"300\" cy=\"52\" r=\"6\" fill=\"#c9a04a\"/><text x=\"255\" y=\"82\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">教師なし学習</text><text x=\"255\" y=\"96\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">答えなしで似た者を仲間分け</text><text x=\"170\" y=\"120\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">同じ「学習」でも、答えの有無で仕組みが違う</text></svg>", "terms": [["教師あり学習", "正解ラベル付きのデータで練習し、新しいデータの正解を予測する学習方法"], ["ラベル", "そのデータにあらかじめ付けられた正解の答えのこと"]], "think": "なぜ「答え付き」で練習させるのかがカギ。機械は、答え合わせができないと自分の予測が合っているかどうか分からず、直しようがない。答え付きのデータを見せることで、機械は「予測がこれだけずれていた」と分かり、その差を縮める方向に少しずつ調整できる。この「答え合わせをしながら直していく」練習を大量に繰り返した結果、答えのない新しい問題にも近い答えを出せるようになる。", "vs": "教師なし学習は、正解が最初から用意されていないデータを使う。似ている者どうしを機械が自分で見つけて仲間分けするだけで、「これが正解」という答え合わせはしない。答えの有無が、この2つを分ける決定的な違い。", "why_asked": "分類や回帰、この先の混同行列や適合率・再現率は、どれも「教師あり学習で正解と予測を照らし合わせる」ことが前提になっている。この土台を先に押さえないと、あとの用語がなぜ必要なのか分からなくなる。", "usecase": "迷惑メールかどうかを見分けるフィルタ、写真に写っている動物の種類を当てるアプリ、過去の売上データから来月の売上を予測する仕組み。どれも「正解付きの過去データ」で練習させている。", "opt": ["正解。問題と正解がセットになったデータで練習し、新しい問題にも答えられるようにする学び方。", "教師なし学習は正解が用意されていないデータを使い、似た者どうしを機械が自分で仲間分けするやり方で、答え合わせをしながら練習する今回の話とは違う。", "強化学習は、行動した結果として得られる報酬をたよりに、少しずつ良い行動を学んでいくやり方で、問題と正解のペアを見せる練習とは仕組みが違う。", "深層学習は、層を何段も重ねた仕組みを使って学習を行う技術のことで、答え付きか答えなしかという学習の種類そのものを指す言葉ではない。"]}'),

  ('stats8-q03', '機械学習との接点',
   '八百屋がAIに仕事を手伝わせている。1つは写真を見せて「キャベツかレタスか」を当てさせる仕事。もう1つは「このキャベツは何グラムか」を当てさせる仕事。前者、つまり決まったラベルのどちらかを選ばせる仕事にあたるのはどれ？',
   NULL::text,
   '["分類（当てはまるラベルを選ばせる）", "回帰（数値そのものを予測させる）", "クラスタリング（正解なしで仲間分けさせる）", "決定木（分類にも回帰にも使える手法）"]',
   0, '[0]', 'single',
   '{"asked": "予測の答えが「ラベル」か「数値」かで見分ける、機械学習の2大タスク。", "point": "答えが「キャベツ/レタス」のような決まった種類の名前なら分類、「320g」のような数そのものなら回帰。", "kid": "分類は、いくつか用意された箱（ラベル）のどれに入るかを当てる仕事。回帰は、重さや値段のような数そのものをずばり当てる仕事。同じ「予測」でも、答えの形がまったく違う。", "eg": "くじ引きで「当たり・はずれ」のどちらかを当てるのが分類、くじの箱に入っている玉の個数そのものを当てるのが回帰。当てる対象が「種類」なのか「量」なのかの違い。", "viz": "<svg viewBox=\"0 0 340 118\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">ラベルを当てる / 数値を当てる</text><rect x=\"30\" y=\"34\" width=\"70\" height=\"26\" rx=\"5\" fill=\"#3b82f6\" opacity=\"0.22\" stroke=\"#60a5fa\"/><text x=\"65\" y=\"51\" fill=\"#60a5fa\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">キャベツ</text><rect x=\"108\" y=\"34\" width=\"70\" height=\"26\" rx=\"5\" fill=\"none\" stroke=\"#2a2f3f\"/><text x=\"143\" y=\"51\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">レタス</text><text x=\"104\" y=\"76\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"700\">分類</text><text x=\"104\" y=\"92\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">どちらのラベルかを選ぶ</text><line x1=\"210\" y1=\"52\" x2=\"320\" y2=\"52\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><line x1=\"214\" y1=\"52\" x2=\"214\" y2=\"57\" stroke=\"#2a2f3f\"/><text x=\"214\" y=\"68\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">0g</text><line x1=\"265\" y1=\"52\" x2=\"265\" y2=\"57\" stroke=\"#2a2f3f\"/><text x=\"265\" y=\"68\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">500g</text><line x1=\"316\" y1=\"52\" x2=\"316\" y2=\"57\" stroke=\"#2a2f3f\"/><text x=\"316\" y=\"68\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">1000g</text><circle cx=\"278\" cy=\"52\" r=\"5\" fill=\"#60a5fa\"/><text x=\"278\" y=\"40\" fill=\"#60a5fa\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">320g</text><text x=\"265\" y=\"92\" fill=\"#e8eaf0\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"700\">回帰</text><text x=\"265\" y=\"106\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">数値そのものを予測する</text></svg>", "terms": [["分類", "あらかじめ決まったいくつかのラベルのうち、どれに当てはまるかを予測すること"], ["回帰", "連続した数値そのものを予測すること"]], "think": "なぜこの2つを分けて考えるのかがカギ。答えが「キャベツかレタスか」のような有限個のラベルなら、「どのラベルに一番近いか」を選ぶ仕組みで十分に答えが出せる。ところが答えが「320g」のような無限に近い数値だと、ラベルを選ぶ仕組みでは対応できず、数直線上のどこに近いかを計算して答えを出す仕組みが必要になる。この「答えの形が有限個の種類か、切れ目のない数値か」の違いが、使う仕組みそのものを変えるので、最初に見分ける必要がある。", "vs": "決定木のような手法は、分類にも回帰にも使える「道具」であって、分類・回帰という「タスクの名前」そのものではない。似た場面で出てくるが、片方は目的の名前、もう片方は目的を達成する手段の名前という違いがある。", "why_asked": "この先の混同行列・適合率・再現率・ROC曲線はすべて「分類」を前提にした道具で、回帰にはそのままでは使えない。先に「分類と回帰は答えの形が違う」と押さえておかないと、なぜ専用の道具が要るのか分からなくなる。", "usecase": "迷惑メールかどうか(分類)、写真の動物の種類(分類)、明日の気温(回帰)、来月の売上金額(回帰)。「はい/いいえ・種類」を当てたいのか「数そのもの」を当てたいのかで、最初に選ぶ手法が変わる。", "opt": ["正解。キャベツかレタスかという、決まったラベルのどちらかを選ばせる仕事なので分類にあたる。", "回帰は重さのような数値そのものを予測させる仕事で、ラベルのどちらかを選ばせる今回の話とは答えの形が違う。", "クラスタリングは正解ラベルを教えずに機械が自分で仲間分けする仕事で、キャベツ・レタスという正解ラベルがある今回の話とは前提が違う。", "決定木は分類にも回帰にも使える手法（道具）の名前であって、ラベルを選ぶ仕事そのものの名前ではない。"]}'),

  ('stats8-q04', '機械学習との接点',
   '受験生は問題集で練習してから、本番の入試を受ける。予測AIも同じように、パラメータを調整するためのデータと、まだ一度も見せていない、本当の実力を測るためのデータを、あらかじめ分けておく。この「実力を測るための、学習に使っていないデータ」を何と呼ぶ？',
   NULL::text,
   '["テストデータ（学習に使っていない実力測定用）", "訓練データ（パラメータを調整するための学習用）", "交差検証（分け方を何通りも変えて確認する）", "過剰適合（訓練データを丸暗記してしまう状態）"]',
   0, '[0]', 'single',
   '{"asked": "データを「学習用」と「実力測定用」に分ける理由と、それぞれの名前。", "point": "パラメータの調整に使うのが訓練データ、一度も見せずに実力を測るのがテストデータ。", "kid": "AIに問題を覚えさせて賢くする材料が訓練データ。仕上がったAIの実力を測るために、練習では絶対に使わない別の問題を取っておく。それがテストデータ。", "eg": "受験生が問題集(訓練データ)で練習した後、その問題集の問題をそのまま本番の入試で使ったら、実力を測ったことにならない。本番の入試(テストデータ)は、問題集とは別の、一度も見たことがない問題であるべき。", "viz": "<svg viewBox=\"0 0 340 124\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"18\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">問題集で練習してから、本番のテストを受ける</text><rect x=\"20\" y=\"38\" width=\"220\" height=\"34\" fill=\"#3b82f6\" opacity=\"0.22\" stroke=\"#60a5fa\"/><text x=\"130\" y=\"59\" fill=\"#60a5fa\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">訓練データ (80問)</text><rect x=\"240\" y=\"38\" width=\"80\" height=\"34\" fill=\"#c9a04a\" opacity=\"0.22\" stroke=\"#c9a04a\"/><text x=\"280\" y=\"59\" fill=\"#c9a04a\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">テスト (20問)</text><text x=\"130\" y=\"92\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">ここでAIの中身(パラメータ)を調整する</text><text x=\"280\" y=\"92\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">ここは覚えさせない</text><text x=\"170\" y=\"112\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">一度も見せていない問題で、本当の実力を測る</text></svg>", "terms": [["訓練データ", "AIのパラメータを調整するために使う学習用のデータ"], ["テストデータ", "学習には使わず、仕上がったAIの実力を測るために取っておくデータ"]], "think": "なぜわざわざデータを分けておくのかがカギ。もし練習に使った問題と同じ問題で実力を測ったら、AIはその問題の答えを丸暗記しているだけかもしれず、本当に新しい問題にも対応できるかは分からない。学習に一度も使っていないデータで測って初めて、「見たことのない問題にも対応できるか」という本当の実力が分かる。だから訓練データとテストデータを、最初から重ならないように分けておく必要がある。", "vs": "交差検証は、この「訓練とテストへの分け方」を何通りも変えて、複数回確かめる、さらに一歩進んだやり方。訓練データとテストデータに分けること自体は、交差検証をする・しないにかかわらず必要な、いちばん基本の準備。", "why_asked": "この先に出てくる過剰適合(丸暗記のしすぎ)は、「訓練データでは良い点だが、テストデータでは崩れる」という形で見つかる。訓練とテストを分ける仕組みを知らないと、過剰適合をどうやって見つけるのかが分からない。", "usecase": "AIモデルを作る現場では、集めたデータの8割を訓練データ、残り2割をテストデータに分ける、といった比率がよく使われる。画像認識アプリや音声認識アプリの開発でも、必ずこの2つに分けてから性能を報告する。", "opt": ["正解。学習には一度も使わず、仕上がったAIの本当の実力を測るために取っておくデータがテストデータ。", "訓練データはAIのパラメータを調整するための学習用データで、実力を測るために取っておく今回のデータとは役目が違う。", "交差検証は訓練とテストへの分け方を何通りも変えて確かめるやり方で、分け方そのものではなく、確かめる手順の名前。", "過剰適合は訓練データを丸暗記しすぎて本番で崩れる状態のことで、実力を測るためのデータそのものの名前ではない。"]}'),

  ('stats8-q05', '機械学習との接点',
   'ある生徒は過去問の答えを丸暗記して、過去問そっくりの問題は満点だった。ところが少し形を変えた新しい問題になると、急に成績が崩れてしまった。このように、訓練データを覚えすぎて、新しいデータでは成績が崩れる現象を何と呼ぶ？',
   NULL::text,
   '["過剰適合（訓練データを丸暗記して崩れる）", "過小適合（単純すぎてどちらも当てられない）", "交差検証（分け方を何度も変えて確かめる）", "テストデータ（本番の実力を測るためのデータ）"]',
   0, '[0]', 'single',
   '{"asked": "訓練データに合わせすぎて、新しいデータに対応できなくなる現象の名前。", "point": "訓練データではほぼ満点、テストデータでは急に崩れる、この差が過剰適合のサイン。", "kid": "過剰適合は、AIが訓練データの細かいクセまで丸ごと覚えてしまい、そのデータだけにやたら詳しくなった状態。丸暗記のしすぎで、少しでも形が変わった新しい問題には対応できなくなる。", "eg": "過去問の答えの並び順（1番はイ、2番はウ…）まで丸暗記した生徒は、問題の順番が変わっただけで全滅する。問題の意味ではなく、訓練データの見た目そのものを覚えてしまった状態が過剰適合。", "viz": "<svg viewBox=\"0 0 340 118\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><g transform=\"translate(30,26)\"><circle cx=\"22\" cy=\"0\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"40\" cy=\"10\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"16\" cy=\"24\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"34\" cy=\"34\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"74\" cy=\"4\" r=\"3.5\" fill=\"#c9a04a\"/><circle cx=\"56\" cy=\"16\" r=\"3.5\" fill=\"#c9a04a\"/><circle cx=\"68\" cy=\"28\" r=\"3.5\" fill=\"#c9a04a\"/><circle cx=\"48\" cy=\"38\" r=\"3.5\" fill=\"#c9a04a\"/></g><path d=\"M18 22 C 40 10, 35 30, 55 24 C 75 18, 65 40, 90 30 C 100 26, 95 55, 118 50\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.6\"/><text x=\"74\" y=\"94\" fill=\"#c47070\" font-size=\"9\" text-anchor=\"middle\">訓練データに合わせて</text><text x=\"74\" y=\"106\" fill=\"#c47070\" font-size=\"9\" text-anchor=\"middle\">ぐにゃぐにゃに曲げすぎ</text><g transform=\"translate(190,26)\"><circle cx=\"22\" cy=\"0\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"40\" cy=\"10\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"16\" cy=\"24\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"34\" cy=\"34\" r=\"3.5\" fill=\"#60a5fa\"/><circle cx=\"74\" cy=\"4\" r=\"3.5\" fill=\"#c9a04a\"/><circle cx=\"56\" cy=\"16\" r=\"3.5\" fill=\"#c9a04a\"/><circle cx=\"68\" cy=\"28\" r=\"3.5\" fill=\"#c9a04a\"/><circle cx=\"48\" cy=\"38\" r=\"3.5\" fill=\"#c9a04a\"/></g><path d=\"M186 44 C 220 20, 250 20, 284 44\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.6\"/><text x=\"234\" y=\"94\" fill=\"#6ab08d\" font-size=\"9\" text-anchor=\"middle\">だいたいの傾向だけをとる</text><text x=\"234\" y=\"106\" fill=\"#6ab08d\" font-size=\"9\" text-anchor=\"middle\">新しいデータにも強い</text><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">訓練データの丸暗記 vs 全体の傾向</text></svg>", "terms": [["過剰適合", "訓練データに合わせすぎて、新しいデータへの対応力が落ちる状態"], ["汎化", "訓練データだけでなく、新しいデータにもうまく対応できる力のこと"]], "think": "なぜ訓練データの丸暗記が悪いのかがカギ。本当に欲しいのは「まだ見ていない新しいデータにも通用する力（汎化）」であって、「訓練データだけで満点を取る力」ではない。訓練データには本来の傾向のほかに、たまたま混ざった細かいノイズも含まれている。境界線を訓練データに完全に合わせようとすると、本来の傾向だけでなくノイズの形までなぞってしまい、ぐにゃぐにゃに曲がった境界線になる。新しいデータはそのノイズの形までは持っていないので、ぐにゃぐにゃの境界線では当てられなくなる。だから、訓練データにぴったり合わせすぎないことが、新しいデータへの強さにつながる。", "vs": "過小適合は逆に、単純にしすぎて訓練データすらうまく当てられない状態。過剰適合は「合わせすぎ」、過小適合は「合わせなさすぎ」で、どちらも新しいデータへの対応力を落とす点は同じだが、原因は正反対。", "why_asked": "「訓練データでの点数だけを見て安心してはいけない」という、機械学習でいちばん最初につまずくポイントだから。この後の交差検証も、過剰適合を早期に見つけて防ぐための工夫として生まれている。", "usecase": "画像認識AIが訓練に使った写真の背景まで覚えてしまい、背景が違う新しい写真では急に間違えるようになる、といった事故は現場でよく起きる。開発者は訓練データとテストデータの点数差を常にチェックして、この事故を防ぐ。", "opt": ["正解。訓練データの細かいクセまで丸暗記してしまい、少し形が変わった新しいデータには対応できなくなる状態。", "過小適合は逆に単純にしすぎて、訓練データすらうまく当てられない状態で、訓練データでは満点だった今回の話とは逆の失敗。", "交差検証は分け方を変えて何度も確かめるやり方のことで、覚えすぎて崩れる現象そのものの名前ではない。", "テストデータは実力を測るためのデータのことで、覚えすぎて崩れるという現象そのものの名前ではない。"]}'),

  ('stats8-q06', '機械学習との接点',
   'クラスで席替えを5回繰り返し、毎回違うグループを「今回の確認係」にして、残り全員を「今回の練習グループ」にする、という方法で、たまたま1回だけ良い結果が出た偶然を防ぎたい。このように、データの分け方を何通りも変えて、複数回テストして性能を確かめる方法を何と呼ぶ？',
   NULL::text,
   '["交差検証（分け方を何度も変えて確かめる）", "テストデータ（本番の実力を測るためのデータ）", "過剰適合（訓練データを丸暗記してしまう状態）", "決定木（質問を重ねて予測する手法）"]',
   0, '[0]', 'single',
   '{"asked": "1回の分け方だけに頼らず、何度も確かめて性能をより信頼できる数字にする方法。", "point": "分け方を何通りも変えて複数回テストし、その平均を見るのが交差検証。1回のたまたまに惑わされない。", "kid": "交差検証は、データの分け方を何パターンも用意して、そのたびに訓練とテストをやり直す方法。5パターン試したら5回分の点数が出るので、その平均を見れば「たまたま良い(悪い)分け方だっただけ」を防げる。", "eg": "テストの手応えを1回の模試だけで判断すると、その日のたまたま得意な問題が多かっただけかもしれない。5回分の模試の平均点を見れば、実力により近い数字になる。分け方を変えて5回試す交差検証も同じ発想。", "viz": "<svg viewBox=\"0 0 340 146\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">分け方を5通り替えて、毎回テストする</text><rect x=\"30\" y=\"24\" width=\"10\" height=\"10\" fill=\"#c9a04a\"/><text x=\"44\" y=\"33\" fill=\"#c9a04a\" font-size=\"8.5\" text-anchor=\"start\">テスト役</text><rect x=\"102\" y=\"24\" width=\"10\" height=\"10\" fill=\"#2a2f3f\" stroke=\"#8892a4\"/><text x=\"116\" y=\"33\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"start\">学習役</text><rect x=\"40\" y=\"46\" width=\"50\" height=\"13\" rx=\"2\" fill=\"#c9a04a\" opacity=\"0.55\" stroke=\"#2a2f3f\"/><rect x=\"94\" y=\"46\" width=\"50\" height=\"13\" rx=\"2\" fill=\"#2a2f3f\" opacity=\"1\" stroke=\"#2a2f3f\"/><rect x=\"148\" y=\"46\" width=\"50\" height=\"13\" rx=\"2\" fill=\"#2a2f3f\" opacity=\"1\" stroke=\"#2a2f3f\"/><rect x=\"202\" y=\"46\" width=\"50\" height=\"13\" rx=\"2\" fill=\"#2a2f3f\" opacity=\"1\" stroke=\"#2a2f3f\"/><rect x=\"256\" y=\"46\" width=\"50\" height=\"13\" rx=\"2\" fill=\"#2a2f3f\" opacity=\"1\" stroke=\"#2a2f3f\"/><text x=\"314\" y=\"56\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"start\">1回目</text><rect x=\"40\" y=\"63\" width=\"50\" height=\"13\" rx=\"2\" fill=\"#2a2f3f\" opacity=\"1\" stroke=\"#2a2f3f\"/><rect x=\"94\" y=\"63\" width=\"50\" height=\"13\" rx=\"2\" fill=\"#c9a04a\" opacity=\"0.55\" stroke=\"#2a2f3f\"/><rect x=\"148\" y=\"63\" width=\"50\" height=\"13\" rx=\"2\" fill=\"#2a2f3f\" opacity=\"1\" stroke=\"#2a2f3f\"/><rect x=\"202\" y=\"63\" width=\"50\" height=\"13\" rx=\"2\" fill=\"#2a2f3f\" opacity=\"1\" stroke=\"#2a2f3f\"/><rect x=\"256\" y=\"63\" width=\"50\" height=\"13\" rx=\"2\" fill=\"#2a2f3f\" opacity=\"1\" stroke=\"#2a2f3f\"/><text x=\"314\" y=\"73\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"start\">2回目</text><rect x=\"40\" y=\"80\" width=\"50\" height=\"13\" rx=\"2\" fill=\"#2a2f3f\" opacity=\"1\" stroke=\"#2a2f3f\"/><rect x=\"94\" y=\"80\" width=\"50\" height=\"13\" rx=\"2\" fill=\"#2a2f3f\" opacity=\"1\" stroke=\"#2a2f3f\"/><rect x=\"148\" y=\"80\" width=\"50\" height=\"13\" rx=\"2\" fill=\"#c9a04a\" opacity=\"0.55\" stroke=\"#2a2f3f\"/><rect x=\"202\" y=\"80\" width=\"50\" height=\"13\" rx=\"2\" fill=\"#2a2f3f\" opacity=\"1\" stroke=\"#2a2f3f\"/><rect x=\"256\" y=\"80\" width=\"50\" height=\"13\" rx=\"2\" fill=\"#2a2f3f\" opacity=\"1\" stroke=\"#2a2f3f\"/><text x=\"314\" y=\"90\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"start\">3回目</text><rect x=\"40\" y=\"97\" width=\"50\" height=\"13\" rx=\"2\" fill=\"#2a2f3f\" opacity=\"1\" stroke=\"#2a2f3f\"/><rect x=\"94\" y=\"97\" width=\"50\" height=\"13\" rx=\"2\" fill=\"#2a2f3f\" opacity=\"1\" stroke=\"#2a2f3f\"/><rect x=\"148\" y=\"97\" width=\"50\" height=\"13\" rx=\"2\" fill=\"#2a2f3f\" opacity=\"1\" stroke=\"#2a2f3f\"/><rect x=\"202\" y=\"97\" width=\"50\" height=\"13\" rx=\"2\" fill=\"#c9a04a\" opacity=\"0.55\" stroke=\"#2a2f3f\"/><rect x=\"256\" y=\"97\" width=\"50\" height=\"13\" rx=\"2\" fill=\"#2a2f3f\" opacity=\"1\" stroke=\"#2a2f3f\"/><text x=\"314\" y=\"107\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"start\">4回目</text><rect x=\"40\" y=\"114\" width=\"50\" height=\"13\" rx=\"2\" fill=\"#2a2f3f\" opacity=\"1\" stroke=\"#2a2f3f\"/><rect x=\"94\" y=\"114\" width=\"50\" height=\"13\" rx=\"2\" fill=\"#2a2f3f\" opacity=\"1\" stroke=\"#2a2f3f\"/><rect x=\"148\" y=\"114\" width=\"50\" height=\"13\" rx=\"2\" fill=\"#2a2f3f\" opacity=\"1\" stroke=\"#2a2f3f\"/><rect x=\"202\" y=\"114\" width=\"50\" height=\"13\" rx=\"2\" fill=\"#2a2f3f\" opacity=\"1\" stroke=\"#2a2f3f\"/><rect x=\"256\" y=\"114\" width=\"50\" height=\"13\" rx=\"2\" fill=\"#c9a04a\" opacity=\"0.55\" stroke=\"#2a2f3f\"/><text x=\"314\" y=\"124\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"start\">5回目</text></svg>", "terms": [["交差検証", "データの分け方を複数パターン用意し、それぞれで訓練とテストを行って平均の性能を見る方法"], ["k分割交差検証", "データをk個のかたまりに分け、毎回1つをテスト役、残りを訓練役にして、k回繰り返すやり方"]], "think": "なぜ1回の分け方だけでは足りないのかがカギ。データをたった1通りに分けてテストすると、その1回のテストデータがたまたま簡単だった(または難しかった)だけで、実力とは違う数字が出ることがある。分け方を5通り用意して、毎回どこかのかたまりをテスト役に回すようにすれば、全部のデータが一度はテスト役になる。5回分の点数の平均を取れば、たまたまの当たり外れが打ち消し合い、より信頼できる実力の数字に近づく。", "vs": "訓練データとテストデータに1回だけ分けるやり方は手軽だが、その1回の分け方の運に左右されやすい。交差検証は手間がかかる分、その運のブレを抑えられる、より確かめの精度が高いやり方。", "why_asked": "過剰適合を早めに見つけるには、1回のテストだけでなく何度も確かめる姿勢が欠かせない。手元のデータが少ないときほど、1回の分け方の偶然に振り回されやすいので、交差検証の考え方が重要になる。", "usecase": "新しい予測モデルを作った研究者が「このモデルの精度は85%です」と発表するとき、その裏では交差検証で何回も確かめた平均の数字であることが多い。手元のデータが少ない医療データの分析などでは特によく使われる。", "opt": ["正解。データの分け方を何通りも変えて複数回テストし、その平均を見ることで、たまたまの結果に惑わされないようにする方法。", "テストデータは実力を測るための1回分のデータのことで、分け方を何度も変えて確かめる手順そのものの名前ではない。", "過剰適合は訓練データを丸暗記しすぎて崩れる状態のことで、分け方を何度も変えて確かめる手順の名前ではない。", "決定木は質問を重ねて予測する手法（道具）の名前で、データの分け方を何度も変えて確かめる手順とは別物。"]}'),

  ('stats8-q07', '機械学習との接点',
   '健康診断で「病気かどうか」をAIが判定した結果と、本当の診断結果を並べて、当たった/外れたを4パターンに整理したい。「予測=陽性/陰性」と「実際=陽性/陰性」の組み合わせを4マスに整理した表を何と呼ぶ？',
   NULL::text,
   '["混同行列（当たり外れを4マスに整理した表）", "ROC曲線（判定ラインを動かして描く曲線）", "決定木（質問を重ねて予測する手法）", "交差検証（分け方を変えて何度も確かめる）"]',
   0, '[0]', 'single',
   '{"asked": "分類の当たり外れを整理する表の名前と、4マスの意味。", "point": "「予測」と「実際」を縦横に並べた4マスの表が混同行列。当たりが2種類、外れが2種類ある。", "kid": "混同行列は、AIの予測と本当の答えを付き合わせて、「両方とも陽性(当たり)」「両方とも陰性(当たり)」「予測だけ陽性(誤検挙)」「予測だけ陰性(見逃し)」の4パターンに数えて整理した表。", "eg": "テストの採点で「◯だと思って書いたら本当に◯だった」「×だと思って書いたら本当に×だった」という2つの当たりと、「◯だと思ったのに×だった」「×だと思ったのに◯だった」という2つの外れを、まとめて数えた成績表のようなもの。", "viz": "<svg viewBox=\"0 0 340 124\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">予測と実際の当たり外れを4マスに整理</text><text x=\"149.0\" y=\"30\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">予測=陽性</text><text x=\"239.0\" y=\"30\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">予測=陰性</text><text x=\"48\" y=\"62.0\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">実際=陽性</text><text x=\"48\" y=\"98.0\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">実際=陰性</text><rect x=\"106\" y=\"40\" width=\"86\" height=\"32\" rx=\"4\" fill=\"#6ab08d\" opacity=\"0.18\" stroke=\"#6ab08d\"/><text x=\"149.0\" y=\"56\" fill=\"#6ab08d\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"700\">TP</text><text x=\"149.0\" y=\"69\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">当たり</text><rect x=\"196\" y=\"40\" width=\"86\" height=\"32\" rx=\"4\" fill=\"#c47070\" opacity=\"0.18\" stroke=\"#c47070\"/><text x=\"239.0\" y=\"56\" fill=\"#c47070\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"700\">FN</text><text x=\"239.0\" y=\"69\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">見逃し</text><rect x=\"106\" y=\"76\" width=\"86\" height=\"32\" rx=\"4\" fill=\"#c47070\" opacity=\"0.18\" stroke=\"#c47070\"/><text x=\"149.0\" y=\"92\" fill=\"#c47070\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"700\">FP</text><text x=\"149.0\" y=\"105\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">誤検挙</text><rect x=\"196\" y=\"76\" width=\"86\" height=\"32\" rx=\"4\" fill=\"#6ab08d\" opacity=\"0.18\" stroke=\"#6ab08d\"/><text x=\"239.0\" y=\"92\" fill=\"#6ab08d\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"700\">TN</text><text x=\"239.0\" y=\"105\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">当たり</text></svg>", "terms": [["混同行列", "予測と実際の組み合わせを4マスに整理した表"], ["TP/FP/FN/TN", "当たり(TP・TN)と外れ(FP・FN)の4パターンの略称"]], "think": "なぜ「当たった数」だけでは足りないのかがカギ。「全体の当たった数」だけを見ると、「病気を病気と当てた当たり」と「健康を健康と当てた当たり」がごちゃまぜになってしまい、「病気の人をどれだけ見逃したか」のような大事な情報が消えてしまう。当たりと外れを4パターンに分けて数えておけば、「見逃し(FN)が多いのか、誤検挙(FP)が多いのか」を後から自由に取り出して比べられる。この4マスが、この先の適合率・再現率・ROC曲線すべての材料になる。", "vs": "ROC曲線は、判定ラインを動かしながら混同行列を何通りも作り、その結果をまとめて1枚の図にしたもの。混同行列は「ある1つの判定ライン」での結果を写した、いわば1枚のスナップ写真にあたる。", "why_asked": "この先に出てくる適合率・再現率・ROC曲線・AUCは、すべてこの4マス(混同行列)の数字から計算される。先にこの表の作り方を押さえておかないと、あとの指標の計算式がただの暗記になってしまう。", "usecase": "病気の検査、迷惑メール判定、不正利用の検知など、「はい/いいえ」を当てるAIの性能を報告するときは、必ずこの4マスの表(混同行列)から始まる。", "opt": ["正解。予測と実際の組み合わせを4マスに整理し、当たりと外れの内訳を見える化した表。", "ROC曲線は判定ラインを動かしながら性能の変化を1枚の図にまとめたもので、ある1つの判定ラインでの結果を写した今回の表とは違う。", "決定木は質問を重ねて予測する手法（道具）の名前で、当たり外れを整理する表そのものの名前ではない。", "交差検証はデータの分け方を何度も変えて確かめる手順のことで、当たり外れを4マスに整理する表そのものではない。"]}'),

  ('stats8-q08', '機械学習との接点',
   '空港の手荷物検査では、「危険物を絶対に見逃さない」ことを最優先にするか、「間違って荷物を止めすぎない」ことを最優先にするかで、確認の厳しさを変える。このうち「危険物と判定した荷物のうち、本当に危険物だった割合」を表す指標はどれ？',
   NULL::text,
   '["適合率（陽性と判定した中で本当に陽性だった割合）", "再現率（本当に陽性だったものを見逃さなかった割合）", "正解率（全体のうち判定が当たっていた割合）", "混同行列（当たり外れを4マスに整理した表）"]',
   0, '[0]', 'single',
   '{"asked": "「判定した中の当たり率」と「本物の中の発見率」、2つの似た指標の見分け方。", "point": "「陽性と判定した中の的中率」が適合率、「本物の陽性を見つけられた割合」が再現率。分母がどちらかを見る。", "kid": "適合率は「危険物と言った荷物のうち、本当に危険物だった割合」。再現率は「本当にあった危険物のうち、ちゃんと危険物だと見つけられた割合」。同じ「割合」でも、母数（分母）にしているものが違う。", "eg": "10個の荷物を「危険物だ」と判定して、そのうち8個が本物の危険物だったら、適合率は8/10。一方、会場全体に本物の危険物が9個あって、そのうち8個を見つけられたら、再現率は8/9。同じ8個の的中でも、比べる母数が違う。", "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">空港検査：見逃しを減らすか、誤検挙を減らすか</text><circle cx=\"140\" cy=\"72\" r=\"46\" fill=\"#3b82f6\" opacity=\"0.16\" stroke=\"#60a5fa\"/><circle cx=\"188\" cy=\"72\" r=\"46\" fill=\"#c9a04a\" opacity=\"0.16\" stroke=\"#c9a04a\"/><text x=\"104\" y=\"40\" fill=\"#60a5fa\" font-size=\"8.5\" text-anchor=\"middle\">危険物と判定した荷物</text><text x=\"226\" y=\"40\" fill=\"#c9a04a\" font-size=\"8.5\" text-anchor=\"middle\">本当に危険物だった荷物</text><text x=\"164\" y=\"76\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"700\">TP</text><text x=\"96\" y=\"92\" fill=\"#c47070\" font-size=\"8.5\" text-anchor=\"middle\">FP\n(誤検挙)</text><text x=\"232\" y=\"92\" fill=\"#c47070\" font-size=\"8.5\" text-anchor=\"middle\">FN\n(見逃し)</text><text x=\"90\" y=\"128\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"start\">適合率=TP/(TP+FP)</text><text x=\"90\" y=\"140\" fill=\"#c9a04a\" font-size=\"9\" text-anchor=\"start\">再現率=TP/(TP+FN)</text></svg>", "terms": [["適合率", "陽性と判定したものの中で、本当に陽性だった割合（TP÷(TP+FP)）"], ["再現率", "本当に陽性だったものの中で、正しく陽性と判定できた割合（TP÷(TP+FN)）"]], "think": "なぜ2つの指標が要るのかがカギ。「誤検挙(FP)を減らしたい」と「見逃し(FN)を減らしたい」は、多くの場合どちらか一方を優先すると、もう一方が悪化するトレードオフの関係にある。判定を厳しくすれば見逃しは減るが、疑わしいものまで止めてしまい誤検挙が増える。逆に判定を緩めれば誤検挙は減るが、見逃しが増える。「誤検挙を測る適合率」と「見逃しを測る再現率」を分けて用意しておくことで、今回の検査は見逃しを最優先にしたいのか、誤検挙を減らしたいのかを、数字ではっきり議論できるようになる。", "vs": "正解率は「陽性・陰性を問わず、全体のうちどれだけ当たったか」を見る大まかな指標で、見逃しと誤検挙のどちらが多いかまでは教えてくれない。危険物のように件数が少ないものを扱うときは、正解率だけでは見逃しに気づけないことがある。", "why_asked": "「精度が高い」と一言で言っても、見逃しに強いのか、誤検挙に強いのかはまったく別の性能である。この2つを区別できないと、目的に合わないAIを選んでしまう危険がある。", "usecase": "がん検診のAIは見逃し(再現率)を最優先にすることが多く、多少の誤検挙(適合率の低下)は再検査で補う。逆に迷惑メール判定は、大事なメールを誤って迷惑メール扱いしない(適合率)ことを優先することが多い。", "opt": ["正解。危険物と判定した荷物のうち、本当に危険物だった割合なので適合率にあたる。", "再現率は、本当にあった危険物のうち、見逃さずに見つけられた割合のことで、判定した中の的中率を問う今回の話とは母数が違う。", "正解率は陽性・陰性を問わず全体のうちの当たり具合を見る指標で、判定した中の的中率だけを見る今回の話とは違う。", "混同行列は当たり外れを4マスに整理した表そのものの名前で、その表から計算される割合の名前ではない。"]}'),

  ('stats8-q09', '機械学習との接点',
   '空港検査の判定ライン(何%以上を危険物とみなすかの線)を厳しくしたり緩めたりすると、見逃す数と誤検挙の数のバランスが変わる。この判定ラインをいろいろ動かしたときの性能の変化をまとめて1枚の図にし、線の下側の面積で「当てる力」を1つの数字にする図と、その面積の名前の組み合わせはどれ？',
   NULL::text,
   '["ROC曲線とAUC（性能の変化を1枚にした図と面積）", "混同行列（ある1つの判定ラインでの当たり外れの表）", "適合率と再現率（ある1つの判定ラインでの2つの指標）", "交差検証（データの分け方を何通りも変えて確かめる）"]',
   0, '[0]', 'single',
   '{"asked": "判定ラインを動かしたときの性能変化を1枚にまとめる図と、その良さを1つの数字にする方法。", "point": "判定ラインを動かしながら描いた曲線がROC曲線、その下の面積が0.5(当てずっぽう)より1に近いほど当てる力が高いAUC。", "kid": "ROC曲線は、判定ラインを厳しくしたり緩めたりしながら、「見逃さず当てられた割合」と「間違って陽性にしてしまった割合」の組をたくさん打って線でつないだグラフ。AUCは、その線の下側の面積のことで、1に近いほど「どんな判定ラインでもよく当たるAI」だと言える。", "eg": "空港検査の厳しさを少しずつ変えながら、そのたびに「見逃さず止められた割合」と「間違って止めてしまった割合」をメモしていくと、点がたくさんできる。その点をつないだ線がROC曲線で、線が左上のかどにぴったり張り付くほど優秀。線の下の面積(AUC)は、その優秀さを1つの数字にしたもの。", "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><line x1=\"46\" y1=\"20\" x2=\"46\" y2=\"118\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><line x1=\"46\" y1=\"118\" x2=\"300\" y2=\"118\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><text x=\"46\" y=\"132\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">0</text><text x=\"300\" y=\"132\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">1 (誤検挙の割合)</text><text x=\"30\" y=\"118\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">0</text><text x=\"20\" y=\"24\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">1</text><line x1=\"46\" y1=\"118\" x2=\"300\" y2=\"20\" stroke=\"#8892a4\" stroke-dasharray=\"4 3\"/><text x=\"230\" y=\"60\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">当てずっぽう</text><path d=\"M46 118 C 90 50, 140 30, 300 20 L300 118 L46 118 Z\" fill=\"#3b82f6\" opacity=\"0.14\"/><path d=\"M46 118 C 90 50, 140 30, 300 20\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"2\"/><text x=\"150\" y=\"92\" fill=\"#60a5fa\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">AUC = 曲線の下の面積</text><text x=\"170\" y=\"12\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">判定ラインを動かしたときの性能を1枚に</text></svg>", "terms": [["ROC曲線", "判定ラインを動かしながら、見逃さない割合と誤検挙の割合の組を線でつないだグラフ"], ["AUC", "ROC曲線の下側の面積。0.5が当てずっぽう、1に近いほど性能が高い"]], "think": "なぜ1つの判定ラインだけで判断しないのかがカギ。適合率や再現率は「ある1つの判定ライン」での性能しか教えてくれず、判定ラインを変えたら数字が大きく変わることがある。判定ラインの選び方しだいで良く見えたり悪く見えたりするAIを、公平に比べるには、判定ラインをあらゆる場合について動かしてみて、その全体の傾向を見る必要がある。ROC曲線は判定ラインを全部動かした結果を1枚の図に描き切り、AUCはその図全体の良さを1つの数字にまとめる。だから判定ラインの選び方に左右されない、公平な比較ができる。", "vs": "混同行列や適合率・再現率は「ある1つの判定ライン」を選んだあとの結果。ROC曲線とAUCは、その判定ラインをあらゆるパターンで動かした「全体像」を見る指標で、見ている範囲の広さが違う。", "why_asked": "「このAIとあのAI、どちらが優秀か」を判定ラインの選び方に左右されずに比べたい場面は多い。AUCという1つの数字にまとめられることで、複数のAIモデルの性能を公平に比較できるようになる。", "usecase": "病気診断AIの性能比較や、迷惑メールフィルタの性能報告では、「AUC=0.92」のように1つの数字で性能を語ることが多い。判定ラインをどう決めるかは、あとから利用者側の目的に合わせて選べる。", "opt": ["正解。判定ラインを動かしながら性能の変化を1枚の図にまとめ、その下の面積で当てる力を1つの数字にする組み合わせ。", "混同行列はある1つの判定ラインでの当たり外れを整理した表で、判定ラインを動かしながら全体を見る今回の話とは範囲が違う。", "適合率と再現率もある1つの判定ラインでの指標で、判定ラインをあらゆるパターンで動かして全体をまとめる今回の話とは範囲が違う。", "交差検証はデータの分け方を何通りも変えて確かめる方法のことで、判定ラインを動かして性能をまとめる図とは別の話。"]}'),

  ('stats8-q10', '機械学習との接点',
   '「今日傘を持っていくか」を、「雨が降りそうか」→「風は強いか」の順に、はい/いいえの質問を重ねて決めることにした。このように、はい/いいえの質問を何段も重ねて予測する方法を何と呼ぶ？',
   NULL::text,
   '["決定木（はい・いいえの質問を重ねて予測する）", "クラスタリング（正解なしで似た者同士に分ける）", "混同行列（当たり外れを4マスに整理した表）", "ROC曲線（判定ラインを動かして描く曲線）"]',
   0, '[0]', 'single',
   '{"asked": "はい/いいえの質問を重ねて答えにたどり着く予測方法の名前。", "point": "1つの質問で枝分かれし、その先でまた質問で枝分かれし…と繰り返して、最後にたどり着いた答えを予測とするのが決定木。", "kid": "決定木は、「雨が降りそう?」「はいなら次に、風は強い?」のように、質問を重ねて枝分かれしていき、最後の行き止まり(葉)にたどり着いた答えを予測結果にする方法。木を逆さまにしたような形になるので決定木と呼ぶ。", "eg": "病院の問診票で「熱はありますか?」「はいなら、せきは出ますか?」のように、質問を重ねて診断の候補を絞り込んでいく流れとそっくり。質問1つ1つが枝分かれの分かれ道になっている。", "viz": "<svg viewBox=\"0 0 340 146\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><rect x=\"128\" y=\"14\" width=\"84\" height=\"26\" rx=\"5\" fill=\"none\" stroke=\"#60a5fa\"/><text x=\"170\" y=\"31\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">雨が降りそう?</text><line x1=\"150\" y1=\"40\" x2=\"90\" y2=\"66\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><polygon points=\"90,66 94.1,61.7 96.0,65.9\" fill=\"#60a5fa\"/><text x=\"112\" y=\"56\" fill=\"#60a5fa\" font-size=\"8.5\" text-anchor=\"middle\">はい</text><line x1=\"190\" y1=\"40\" x2=\"250\" y2=\"66\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><polygon points=\"250,66 244.0,65.9 245.9,61.7\" fill=\"#60a5fa\"/><text x=\"228\" y=\"56\" fill=\"#60a5fa\" font-size=\"8.5\" text-anchor=\"middle\">いいえ</text><rect x=\"46\" y=\"66\" width=\"88\" height=\"26\" rx=\"5\" fill=\"none\" stroke=\"#8892a4\"/><text x=\"90\" y=\"83\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">風は強い?</text><rect x=\"212\" y=\"66\" width=\"92\" height=\"26\" rx=\"5\" fill=\"#6ab08d\" opacity=\"0.2\" stroke=\"#6ab08d\"/><text x=\"258\" y=\"83\" fill=\"#6ab08d\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">傘はいらない</text><line x1=\"66\" y1=\"92\" x2=\"40\" y2=\"116\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><polygon points=\"40,116 42.5,110.5 45.6,114.0\" fill=\"#60a5fa\"/><text x=\"37\" y=\"108\" fill=\"#60a5fa\" font-size=\"8.5\" text-anchor=\"middle\">はい</text><line x1=\"114\" y1=\"92\" x2=\"140\" y2=\"116\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><polygon points=\"140,116 134.4,114.0 137.5,110.5\" fill=\"#60a5fa\"/><text x=\"143\" y=\"108\" fill=\"#60a5fa\" font-size=\"8.5\" text-anchor=\"middle\">いいえ</text><rect x=\"10\" y=\"116\" width=\"70\" height=\"24\" rx=\"5\" fill=\"#3b82f6\" opacity=\"0.2\" stroke=\"#60a5fa\"/><text x=\"45\" y=\"132\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">傘は必須</text><rect x=\"106\" y=\"116\" width=\"80\" height=\"24\" rx=\"5\" fill=\"#c9a04a\" opacity=\"0.2\" stroke=\"#c9a04a\"/><text x=\"146\" y=\"132\" fill=\"#c9a04a\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">念のため持つ</text></svg>", "terms": [["決定木", "質問による枝分かれを何段も重ねて予測を行う手法"], ["葉（リーフ）", "決定木の一番先、それ以上枝分かれしない行き止まりの部分。ここが最終的な予測結果になる"]], "think": "なぜ質問を1つで終わらせず、何段も重ねるのかがカギ。「雨が降りそうか」だけでは、小雨で風もない日と、大雨で風も強い日を同じ「傘がいる」に丸めてしまい、判断が粗くなる。そこで「風は強いか」という2つ目の質問を追加すると、「小雨で風は弱い→念のため持つ」のように、より細かく状況を分けて答えを出せる。質問を重ねるほど、状況を細かく分けて的確な答えに近づけられる。ただし重ねすぎると、細かく分けすぎて訓練データの丸暗記(過剰適合)に近づいてしまう点には注意がいる。", "vs": "クラスタリングは正解を教えずに機械が自分で似た者どうしを見つける方法。決定木は「どの質問をどの順番でするか」を、正解データを見ながら学んでいく方法で、正解の有無が違う。", "why_asked": "決定木は、なぜその予測になったのかを「どの質問にどう答えたから」という形で人にも説明しやすい、数少ない機械学習の手法。統計の「理由を説明したい」という発想と、機械学習の「予測を当てたい」という発想の橋渡しになる手法として押さえておく価値がある。", "usecase": "ローン審査(収入は?延滞歴は?の質問を重ねて可否を判断)、病気の診断補助、迷惑メール判定など、「なぜその判断になったか」を人に説明する必要がある場面でよく使われる。", "opt": ["正解。はい・いいえの質問を何段も重ねて枝分かれさせ、最後にたどり着いた答えを予測とする方法。", "クラスタリングは正解ラベルを教えずに機械が自分で仲間分けする方法で、質問を重ねて答えにたどり着く今回の話とは仕組みが違う。", "混同行列は当たり外れを4マスに整理した表のことで、質問を重ねて予測する方法そのものの名前ではない。", "ROC曲線は判定ラインを動かして描く曲線のことで、質問を重ねて予測する方法そのものの名前ではない。"]}'),

  ('stats8-q11', '機械学習との接点',
   '身長と体重のデータだけがあり、正解ラベルは何もない。それでも、データどうしの近さだけをたよりに、機械が自動でいくつかのグループに仲間分けをした。このように、正解ラベルなしで似ているデータどうしを自動でグループ分けする手法を何と呼ぶ？',
   NULL::text,
   '["クラスタリング（正解なしで仲間分けする）", "決定木（質問を重ねて分類や回帰をする手法）", "教師あり学習（答え付きのデータで練習する）", "次元削減（たくさんの軸を少ない軸にまとめる）"]',
   0, '[0]', 'single',
   '{"asked": "正解ラベルがないデータを、機械が自動でグループ分けする方法の名前。", "point": "正解ラベルなしで、データどうしの近さ(似ている度合い)だけを頼りに、自動でいくつかの仲間に分けるのがクラスタリング。", "kid": "クラスタリングは、「これがグループA」という正解を誰も教えていないのに、身長や体重が近いデータどうしを機械が自動で見つけ出して、いくつかのグループ(クラスタ)にまとめる方法。代表的なやり方にk-means法がある。", "eg": "運動会で、事前に組分けの紙を配らなくても、身長が近い子どうしが自然と近くに集まって並ぶような場面を想像するとよい。誰かが「あなたはA組」と決めたわけではなく、近さだけで自然と固まりができる。", "viz": "<svg viewBox=\"0 0 340 128\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">正解ラベルなしで、似た者どうしを機械が仲間分け</text><circle cx=\"48\" cy=\"42\" r=\"4.5\" fill=\"#60a5fa\"/><circle cx=\"62\" cy=\"54\" r=\"4.5\" fill=\"#60a5fa\"/><circle cx=\"40\" cy=\"60\" r=\"4.5\" fill=\"#60a5fa\"/><circle cx=\"58\" cy=\"70\" r=\"4.5\" fill=\"#60a5fa\"/><circle cx=\"50\" cy=\"34\" r=\"4.5\" fill=\"#60a5fa\"/><circle cx=\"160\" cy=\"40\" r=\"4.5\" fill=\"#c9a04a\"/><circle cx=\"178\" cy=\"50\" r=\"4.5\" fill=\"#c9a04a\"/><circle cx=\"150\" cy=\"58\" r=\"4.5\" fill=\"#c9a04a\"/><circle cx=\"172\" cy=\"66\" r=\"4.5\" fill=\"#c9a04a\"/><circle cx=\"166\" cy=\"34\" r=\"4.5\" fill=\"#c9a04a\"/><circle cx=\"268\" cy=\"44\" r=\"4.5\" fill=\"#6ab08d\"/><circle cx=\"288\" cy=\"56\" r=\"4.5\" fill=\"#6ab08d\"/><circle cx=\"256\" cy=\"64\" r=\"4.5\" fill=\"#6ab08d\"/><circle cx=\"280\" cy=\"72\" r=\"4.5\" fill=\"#6ab08d\"/><circle cx=\"272\" cy=\"34\" r=\"4.5\" fill=\"#6ab08d\"/><circle cx=\"52\" cy=\"52\" r=\"26\" fill=\"none\" stroke=\"#60a5fa\" stroke-dasharray=\"3 3\"/><circle cx=\"165\" cy=\"50\" r=\"26\" fill=\"none\" stroke=\"#c9a04a\" stroke-dasharray=\"3 3\"/><circle cx=\"272\" cy=\"54\" r=\"26\" fill=\"none\" stroke=\"#6ab08d\" stroke-dasharray=\"3 3\"/><text x=\"52\" y=\"96\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\">グループ1</text><text x=\"165\" y=\"96\" fill=\"#c9a04a\" font-size=\"9\" text-anchor=\"middle\">グループ2</text><text x=\"272\" y=\"96\" fill=\"#6ab08d\" font-size=\"9\" text-anchor=\"middle\">グループ3</text><text x=\"170\" y=\"116\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">身長・体重の近さだけで、機械が自動で3つに分けた</text></svg>", "terms": [["クラスタリング", "正解ラベルなしで、データどうしの近さをもとに自動でグループ分けする手法"], ["k-means法", "いくつのグループに分けるかを先に決め、各グループの中心に近いデータを集めていく代表的なクラスタリングの方法"]], "think": "なぜ正解ラベルなしでも仲間分けができるのかがカギ。人がラベルを教えなくても、身長や体重のように「近いデータどうしは似た性質を持つ」という前提があれば、データの散らばり方から自然な固まりを見つけることができる。機械は、まずグループの中心をいくつか適当に置き、各データを一番近い中心のグループに割り当て、そのグループの平均でまた中心を計算し直す、という手順を繰り返す。この繰り返しで、中心とデータの割り当てがだんだん落ち着き、自然な仲間分けができあがる。", "vs": "教師あり学習は正解ラベル付きのデータで練習する方法で、正解を機械に教える。クラスタリングは正解ラベルがないデータから、機械が自分で仲間の固まりを見つける方法で、正解を教えない点が正反対。", "why_asked": "世の中のデータには、正解ラベルを付ける手間がかけられないものが大量にある。そうしたデータからも意味のあるグループを見つけ出したいという要求から、正解なしで仲間分けをするクラスタリングが必要になった。", "usecase": "お店の顧客データを「よく買う客・たまに買う客・新規客」のようなグループに自動で分けるマーケティング分析、写真データを似た色調ごとに自動で仕分けるアプリなど。", "opt": ["正解。正解ラベルなしで、データどうしの近さだけをもとに、自動でいくつかのグループに分ける手法。", "決定木は質問を重ねて分類や回帰を行う手法のことで、正解ラベルを機械に見せながら学ぶ点がクラスタリングとは違う。", "教師あり学習は答え付きのデータで機械に練習させる方法のことで、正解ラベルがない今回の場面とは前提が違う。", "次元削減はたくさんの軸(変数)を少ない軸にまとめる手法のことで、データをいくつかのグループに仲間分けする今回の話とは目的が違う。"]}'),

  ('stats8-q12', '機械学習との接点',
   '生徒のテスト点数が国語・数学・理科・社会・英語の5科目ぶんあるが、細かく5つも見るのは大変なので、「文系力」「理系力」のようなたった2つの軸にまとめて眺めたい。このように、たくさんの軸(変数)の情報をできるだけ保ちながら、少ない軸にまとめる手法を何と呼ぶ？',
   NULL::text,
   '["次元削減（たくさんの軸を少ない軸にまとめる）", "クラスタリング（正解なしで似た者同士に分ける）", "決定木（質問を重ねて分類や回帰をする手法）", "交差検証（データの分け方を変えて確かめる方法）"]',
   0, '[0]', 'single',
   '{"asked": "たくさんの変数を、情報をできるだけ保ったまま少ない軸にまとめる手法の名前。", "point": "データがいちばんよくばらついて見える向きを新しい軸に選び直し、少ない軸でも元の様子ができるだけ分かるようにするのが次元削減。", "kid": "次元削減は、国語・数学・理科・社会・英語という5つの軸(変数)を、情報をなるべく捨てずに、2つや3つといった少ない軸にまとめ直す方法。代表的なやり方に主成分分析(PCA)がある。まとめ直した後の1本目の軸を第1主成分と呼ぶ。", "eg": "太陽の光を横から当てて、立体の物体の影を1枚の壁に映すと、3次元の形の特徴が2次元の影だけでもある程度伝わる。次元削減は、データを一番よく特徴が伝わる向きから「影」を落とすようなもの。", "viz": "<svg viewBox=\"0 0 340 146\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">たくさんの軸を、少ない軸にまとめる</text><line x1=\"40\" y1=\"104\" x2=\"252\" y2=\"18\" stroke=\"#60a5fa\" stroke-width=\"1.8\"/><circle cx=\"60\" cy=\"90\" r=\"3.5\" fill=\"#e8eaf0\"/><circle cx=\"80\" cy=\"78\" r=\"3.5\" fill=\"#e8eaf0\"/><circle cx=\"100\" cy=\"84\" r=\"3.5\" fill=\"#e8eaf0\"/><circle cx=\"120\" cy=\"64\" r=\"3.5\" fill=\"#e8eaf0\"/><circle cx=\"140\" cy=\"70\" r=\"3.5\" fill=\"#e8eaf0\"/><circle cx=\"160\" cy=\"50\" r=\"3.5\" fill=\"#e8eaf0\"/><circle cx=\"180\" cy=\"58\" r=\"3.5\" fill=\"#e8eaf0\"/><circle cx=\"200\" cy=\"38\" r=\"3.5\" fill=\"#e8eaf0\"/><circle cx=\"220\" cy=\"46\" r=\"3.5\" fill=\"#e8eaf0\"/><circle cx=\"240\" cy=\"28\" r=\"3.5\" fill=\"#e8eaf0\"/><line x1=\"60\" y1=\"90\" x2=\"66\" y2=\"98\" stroke=\"#8892a4\" stroke-dasharray=\"2 2\"/><line x1=\"120\" y1=\"64\" x2=\"126\" y2=\"72\" stroke=\"#8892a4\" stroke-dasharray=\"2 2\"/><line x1=\"200\" y1=\"38\" x2=\"206\" y2=\"46\" stroke=\"#8892a4\" stroke-dasharray=\"2 2\"/><text x=\"170\" y=\"118\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">第1主成分の軸 ＝ 点の並びが一番よくばらつく向き</text><text x=\"170\" y=\"134\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">点の影を軸に落とせば、1本の線でも様子がつかめる</text></svg>", "terms": [["次元削減", "たくさんの変数の情報をできるだけ保ちながら、少ない軸にまとめ直す手法"], ["主成分分析（PCA）", "データが一番よくばらついて見える向きを新しい軸として選び直す、代表的な次元削減の手法"]], "think": "なぜ軸を減らしても情報が保てるのかがカギ。国語と英語のように、点数が高い生徒はどちらも高くなりがちな、たがいに似た動きをする科目の組がある。そうした似た動きをする軸をまとめて、「データが一番大きくばらついて見える向き」を新しい1本の軸(第1主成分)として選び直すと、5科目ぶんの違いのかなりの部分を、その1本の軸だけで表せてしまう。ばらつきが大きい向きほど、生徒どうしの違いをよく表しているので、その向きを優先して軸に選ぶことで、少ない軸でも元の様子をなるべく保てる。", "vs": "クラスタリングは「似ているデータどうしをグループに分ける」ことが目的で、軸(変数)の数そのものは変えない。次元削減は「軸の数を減らす」ことが目的で、グループ分けそのものはしない。目的がはっきり違う。", "why_asked": "変数が何十個、何百個もあるデータは、そのままでは人が眺めても機械が計算しても扱いにくい。情報をなるべく落とさずに軸を減らせれば、可視化もしやすくなり、計算の手間も減らせる。この必要性から次元削減が生まれた。", "usecase": "何十個もあるアンケート項目を「満足度」「使いやすさ」のような少数の軸にまとめて分析する、顔画像の何千個ものピクセルの情報を少ない軸にまとめて顔認識を軽くする、といった場面で使われる。", "opt": ["正解。たくさんの軸の情報をできるだけ保ちながら、少ない軸にまとめ直す手法。", "クラスタリングは似ているデータどうしをグループに分ける手法のことで、軸の数を減らす今回の話とは目的が違う。", "決定木は質問を重ねて分類や回帰を行う手法のことで、軸の数を少なくまとめ直す今回の話とは目的が違う。", "交差検証はデータの分け方を変えて何度も確かめる手順のことで、軸の数を少なくまとめ直す今回の話とは別物。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'stats-basics'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
